module tb_TopModule;
    logic [7:0] in;
    logic [2:0] pos;

    TopModule uut (
        .in(in),
        .pos(pos)
    );

    initial begin
        integer i;
        reg [2:0] expected;

        // Test all possible inputs
        for (i = 0; i < 256; i = i + 1) begin
            in = i[7:0];
            #1;
            // Calculate expected independently
            if      (in[0]) expected = 3'd0;
            else if (in[1]) expected = 3'd1;
            else if (in[2]) expected = 3'd2;
            else if (in[3]) expected = 3'd3;
            else if (in[4]) expected = 3'd4;
            else if (in[5]) expected = 3'd5;
            else if (in[6]) expected = 3'd6;
            else if (in[7]) expected = 3'd7;
            else            expected = 3'd0;

            if (pos !== expected) begin
                $display("SELFFAIL: in=%b, expected=%0d, got=%0d", in, expected, pos);
                $finish;
            end
        end

        // Specific test from prompt: 8'b10010000 -> 4
        in = 8'b10010000;
        #1;
        if (pos !== 3'd4) begin
            $display("SELFTEST FAIL: prompt example 8'b10010000 got %0d", pos);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

